const ms = s => { const m = String(s || '').match(/(\d{2})\/(\d{2})\/(\d{4}),?\s+(\d{2}):(\d{2})/); return m ? Date.parse(m[3] + '-' + m[2] + '-' + m[1] + 'T' + m[4] + ':' + m[5] + ':00-03:00') : NaN; };
const lim = Date.now() - 24 * 3600000;
return $('Zelador: ler tickets').all().map(i => i.json).filter(r => r.row_number && String(r.status_ticket || '').trim() === 'aberto' && String(r.ultima_mensagem || '').length > 10 && ms(r.ultima_mensagem) < lim)
  .map(r => ({ json: { row_number: r.row_number, status_ticket: 'encerrado' } }));

// Netliss - Limpeza de expirados (18:59) - clonado do Make.
// Regra do dono: expirado? Exclui. Vale para cliente normal e para teste gratis que ja venceu.
// So entram contas criadas pelo admin (created_by=1) com vencimento ja passado na hora em que roda.
// Teste em andamento (ainda nao vencido) e contas de revendedor nunca entram.
const SIMULAR = true; // true = so confere e lista; nao apaga nada
const H0 = this.helpers;
const seg = n => { const i = $('Limpeza: segredos').all().find(x => x.json.chave === n); return i ? String(i.json.valor || '') : ''; };
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Safari/537.36';
const BASE = 'https://painel.netliss.shop';
const NL = String.fromCharCode(10);
const out = { simulacao: SIMULAR, total: 0, expiradas: 0, clientes: [], testes: [], excluidas: [], andamento: [], falhas: [], semData: [], erros: [], erro: '', pediuExclusao: false, msg: '' };
const espera = ms => new Promise(r => setTimeout(r, ms));
const req = async (url, o) => { const r = await H0.httpRequest(Object.assign({ url, method: 'GET', json: false, timeout: 15000, returnFullResponse: true, ignoreHttpStatusErrors: true, disableFollowRedirect: true }, o || {}));
  let j = null; try { j = typeof r.body === 'string' ? JSON.parse(r.body) : r.body; } catch (e) {} return { status: r.statusCode, headers: r.headers || {}, body: r.body, j }; };
function horaSP(d) { const p = {}; for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'America/Sao_Paulo', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(d)) { p[x.type] = x.value; } return { dm: p.day + '/' + p.month, hm: p.hour + ':' + p.minute }; }
// o painel grava as datas em UTC (AAAA-MM-DD HH:MM:SS); data que nao da para ler = nao mexe na conta
function expMs(s) { s = String(s == null ? '' : s).trim(); if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T][0-9]{2}:[0-9]{2}:[0-9]{2}/.test(s)) { return NaN; } const r = s.slice(19); if (/^([.][0-9]+)?Z?$/.test(r)) { return new Date(s.slice(0, 10) + 'T' + s.slice(11, 19) + 'Z').getTime(); } if (/^([.][0-9]+)?[+-][0-9]{2}:?[0-9]{2}$/.test(r)) { return new Date(s.slice(0, 10) + 'T' + s.slice(11)).getTime(); } return NaN; }
function ehTeste(c) { const v = c ? c.is_test : 0; return v === 1 || v === true || String(v) === '1' || String(v) === 'true'; }
function doAdmin(c) { return !!c && String(c.created_by) === '1' && (c.creator_username == null || String(c.creator_username) === 'admin'); }
function nomes(a, max) { const b = a.slice(0, max).join(', '); return a.length > max ? b + ' e mais ' + (a.length - max) : b; }
function pl(n, um, varios) { return n + ' ' + (n === 1 ? um : varios); }
const agora = Date.now(); const q = horaSP(new Date(agora));
const CAB = (SIMULAR ? '[SIMULAÇÃO] ' : '') + '🧹 Limpeza de expirados (' + q.dm + ' ' + q.hm + ')' + NL + NL;
try {
  // 1) entra no painel
  const nl = await req(BASE + '/api/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json', 'User-Agent': UA }, body: JSON.stringify({ usuario: seg('painel_usuario'), senha: seg('painel_senha') }) });
  let sc = nl.headers['set-cookie'] || []; if (!Array.isArray(sc)) sc = [sc];
  const cookie = sc.map(c => String(c).split(';')[0].trim()).join('; ');
  if (nl.status !== 200 || !cookie) { throw new Error('não consegui entrar no painel (login ' + nl.status + ')'); }
  const xs = (cookie.match(/XSRF-TOKEN=([^;]+)/) || [])[1];
  const H = Object.assign({ 'User-Agent': UA, 'Cookie': cookie, 'Accept': 'application/json' }, xs ? { 'X-XSRF-TOKEN': decodeURIComponent(xs) } : {});
  async function lista(f) { const r = await req(BASE + '/api/accounts?' + f, { headers: H }); const j = r.j; if (r.status !== 200 || !j || j.success !== true || !Array.isArray(j.data)) { throw new Error('o painel não devolveu a lista de contas (' + r.status + ')'); } return j.data; }
  // 2) contas do admin com vencimento ja passado
  const minhas = (await lista('created_by=1')).filter(doAdmin); out.total = minhas.length;
  if (minhas.length === 0) { throw new Error('a lista de contas do admin veio vazia'); }
  const alvo = [];
  for (const c of minhas) { const m = expMs(c.expires_at); if (isNaN(m)) { out.semData.push(String(c.username)); continue; } if (m < agora) { alvo.push(c); } }
  const clientes = alvo.filter(c => !ehTeste(c)); const testes = alvo.filter(c => ehTeste(c));
  out.expiradas = alvo.length; out.clientes = clientes.map(c => String(c.username)); out.testes = testes.map(c => String(c.username));
  const obs = out.semData.length ? NL + NL + 'Obs.: ' + pl(out.semData.length, 'conta', 'contas') + ' com data que não consegui ler. Não mexi nelas.' : '';
  if (alvo.length === 0) { out.msg = CAB + 'Nenhuma conta expirada. Nada a excluir.' + obs; return [{ json: out }]; }
  if (SIMULAR) { out.msg = CAB + 'Apagaria ' + alvo.length + ' (' + pl(clientes.length, 'cliente', 'clientes') + ' e ' + pl(testes.length, 'teste', 'testes') + '): ' + nomes(alvo.map(c => String(c.username)), 40) + obs; return [{ json: out }]; }
  // 3) pede a exclusao pelo id
  out.pediuExclusao = true; const jobs = []; const aceito = {};
  const leJob = j => j ? (j.job_id || (j.data && j.data.job_id) || null) : null;
  let emLote = false;
  if (alvo.length > 1) { const r = await req(BASE + '/api/accounts/delete-multiple', { method: 'POST', headers: Object.assign({ 'Content-Type': 'application/json' }, H), body: JSON.stringify({ ids: alvo.map(c => c.id) }) });
    if (r.status >= 200 && r.status < 300 && r.j && r.j.success !== false) { emLote = true; for (const c of alvo) { aceito[String(c.id)] = 1; } const jb = leJob(r.j); if (jb) { jobs.push(String(jb)); } } else { out.erros.push('lote: ' + r.status + ' ' + String(r.body).slice(0, 120)); } }
  if (!emLote) { for (const c of alvo) { const r = await req(BASE + '/api/accounts/' + c.id, { method: 'DELETE', headers: H });
    if (r.status >= 200 && r.status < 300 && (!r.j || r.j.success !== false)) { aceito[String(c.id)] = 1; const jb = leJob(r.j); if (jb) { jobs.push(String(jb)); } } else { out.erros.push(String(c.username) + ': ' + r.status + ' ' + String(r.body).slice(0, 120)); } } }
  // 4) espera o painel terminar e confere na lista o que saiu de verdade
  let terminou = false; const ver = jobs.slice(0, 3); const fim = Date.now() + 20000;
  if (ver.length === 0) { await espera(2000); }
  while (ver.length && Date.now() < fim) { await espera(1500); let prontos = 0; for (const jb of ver) { const r = await req(BASE + '/api/jobs/deletion/status?job_id=' + encodeURIComponent(jb), { headers: H }); if (r.status !== 200) continue; const s = (r.j && r.j.data) ? r.j.data : (r.j || {}); const st = String(s.state || ''); out.estadoJob = st; if (st === 'completed' || st === 'failed') { prontos++; } } if (prontos === ver.length) { terminou = jobs.length <= 3; break; } }
  const depois = await lista('created_by=1'); const vivo = {}; for (const c of depois) { vivo[String(c.id)] = 1; }
  for (const c of alvo) { const u = String(c.username); if (!vivo[String(c.id)]) { out.excluidas.push(u); } else if (!aceito[String(c.id)] || terminou) { out.falhas.push(u); } else { out.andamento.push(u); } }
  const exC = clientes.map(c => String(c.username)).filter(u => out.excluidas.indexOf(u) >= 0);
  const exT = testes.map(c => String(c.username)).filter(u => out.excluidas.indexOf(u) >= 0);
  let msg = CAB + 'Expiradas encontradas: ' + alvo.length + ' (' + pl(clientes.length, 'cliente', 'clientes') + ' e ' + pl(testes.length, 'teste', 'testes') + ').' + NL + 'Excluídas: ' + out.excluidas.length + '.';
  if (out.andamento.length) { msg += NL + 'Ainda em andamento no painel: ' + out.andamento.length + ' (' + nomes(out.andamento, 15) + ').'; }
  if (out.falhas.length) { msg += NL + 'Não consegui excluir: ' + out.falhas.length + ' (' + nomes(out.falhas, 15) + ').'; }
  if (exC.length) { msg += NL + NL + 'Clientes: ' + nomes(exC, 40) + '.'; }
  if (exT.length) { msg += NL + (exC.length ? '' : NL) + 'Testes: ' + nomes(exT, 40) + '.'; }
  out.msg = msg + obs;
} catch (e) { out.erro = String((e && e.message) || e); out.msg = CAB + '❌ FALHOU: ' + out.erro + '.' + (out.pediuExclusao ? ' A exclusão já tinha sido pedida ao painel. Confira no painel.' : ' Nada foi apagado.'); }
return [{ json: out }];
